import json
def bad(n):
    raise ValueError('bad '+n)
for s in ['{\"a\": NaN}', '{\"a\": Infinity}', '{\"a\": -Infinity}', '{\"a\": null}', '{\"a\": true}']:
    try:
        print(s, '->', json.loads(s, parse_constant=bad))
    except Exception as e:
        print(s, '-> EXC', type(e).__name__, e)
try:
    print(json.loads('{\"a\": 1e400}'))
except Exception as e:
    print('1e400 EXC', e)
